function pointInRing(lat: number, lon: number, ring: RingLatLon): boolean {
  if (!isFinite(lat) || !isFinite(lon) || !ring || ring.length < 3) return false;
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [yi, xi] = ring[i];
    const [yj, xj] = ring[j];
    const den = (yj - yi) || 1e-12;
    const intersect = ((yi > lat) !== (yj > lat)) && (lon < ((xj - xi) * (lat - yi)) / den + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function pointInPolygonWithHoles(lat: number, lon: number, poly: PolygonLatLon): boolean {
  if (!poly || poly.length === 0) return false;
  if (!pointInRing(lat, lon, poly[0])) return false;
  for (let i = 1; i < poly.length; i++) {
    if (pointInRing(lat, lon, poly[i])) return false;
  }
  return true;
}

export function pointInPolygon(lat: number, lon: number, poly: MultiPolygonLatLon): boolean {
  if (!isFinite(lat) || !isFinite(lon) || !poly || poly.length < 1) return false;
  return poly.some((p) => pointInPolygonWithHoles(lat, lon, p));
}

export function getIstanbulDistrictCenter(key: string): { lat: number; lon: number } | null {
  return DISTRICT_CENTERS[key] || null;
}

export function normalizeDistrictKey(raw: string): string | null {
  if (!raw) return null;
  const lower = String(raw).toLocaleLowerCase('tr-TR')
    .replace(/ı/g, 'i').replace(/i̇/g, 'i')
    .replace(/ş/g, 's').replace(/ç/g, 'c').replace(/ğ/g, 'g')
    .replace(/ü/g, 'u').replace(/ö/g, 'o')
    .replace(/[^a-z0-9]/g, '');
  for (const d of ISTANBUL_39_ILCE) {
    if (d.key === lower) return d.key;
    for (const a of d.aliases) {
      const anorm = a.toLocaleLowerCase('tr-TR')
        .replace(/ı/g, 'i').replace(/i̇/g, 'i')
        .replace(/ş/g, 's').replace(/ç/g, 'c').replace(/ğ/g, 'g')
        .replace(/ü/g, 'u').replace(/ö/g, 'o')
        .replace(/[^a-z0-9]/g, '');
      if (lower.includes(anorm) && anorm.length >= 4) return d.key;
    }
  }
  return null;
}

export function pointInIstanbulOuter(lat: number, lon: number): boolean {
  return pointInPolygon(lat, lon, ISTANBUL_OUTER_POLYGON);
}

export function pointInDistrict(lat: number, lon: number, districtKey: string): boolean {
  const d = ISTANBUL_39_ILCE.find(x => x.key === districtKey);
  if (!d) return false;
  return pointInPolygon(lat, lon, d.polygon);
}

export function findDistrictForPoint(lat: number, lon: number): istanbulDistrict | null {
  if (!pointInIstanbulOuter(lat, lon)) return null;
  for (const d of ISTANBUL_39_ILCE) {
    if (pointInPolygon(lat, lon, d.polygon)) return d;
  }
  return null;
}

export function reverseLookupDistrict(displayName: string): istanbulDistrict | null {
  const k = normalizeDistrictKey(displayName);
  if (!k) return null;
  return ISTANBUL_39_ILCE.find(d => d.key === k) || null;
}